import CArgon2
import CryptoKit
import Foundation
import Testing
@testable import VariorumCore

/// Phase 14b batch 1 — the vendored Argon2id build + `PassphraseKDF`.
///
/// Vector provenance (stated per the batch brief): the full-context vector
/// is RFC 9106 §5.3's Argon2id test vector — byte-identical to the pinned
/// upstream's own `kats/argon2id` KAT (the RFC vectors were generated by
/// this reference implementation; both sources checked at vendoring). The
/// raw-API vectors are the pinned upstream's `src/test.c` argon2id cases
/// (which exercise `argon2id_hash_raw`, the API `PassphraseKDF` calls).
@Suite("PassphraseKDF (Phase 14b, batch 1)")
struct PassphraseKDFTests {
    private func hex(_ data: Data) -> String {
        data.map { String(format: "%02x", $0) }.joined()
    }

    private func keyHex(_ key: SymmetricKey) -> String {
        hex(key.withUnsafeBytes { Data($0) })
    }

    // MARK: - RFC 9106 §5.3 (full-context: secret + associated data)

    @Test func rfc9106Argon2idVector() {
        // Password 32×0x01 · salt 16×0x02 · secret 8×0x03 · ad 12×0x04 ·
        // t=3 · m=32 KiB · p=4 lanes · tag 32 bytes · version 0x13.
        let outLen = 32
        let out = UnsafeMutablePointer<UInt8>.allocate(capacity: outLen)
        defer { out.deallocate() }
        let pwd = UnsafeMutablePointer<UInt8>.allocate(capacity: 32)
        defer { pwd.deallocate() }
        pwd.initialize(repeating: 0x01, count: 32)
        let salt = UnsafeMutablePointer<UInt8>.allocate(capacity: 16)
        defer { salt.deallocate() }
        salt.initialize(repeating: 0x02, count: 16)
        let secret = UnsafeMutablePointer<UInt8>.allocate(capacity: 8)
        defer { secret.deallocate() }
        secret.initialize(repeating: 0x03, count: 8)
        let ad = UnsafeMutablePointer<UInt8>.allocate(capacity: 12)
        defer { ad.deallocate() }
        ad.initialize(repeating: 0x04, count: 12)

        var context = argon2_context(
            out: out, outlen: UInt32(outLen),
            pwd: pwd, pwdlen: 32,
            salt: salt, saltlen: 16,
            secret: secret, secretlen: 8,
            ad: ad, adlen: 12,
            t_cost: 3, m_cost: 32, lanes: 4, threads: 1,
            version: UInt32(ARGON2_VERSION_13.rawValue),
            allocate_cbk: nil, free_cbk: nil,
            flags: 0  // ARGON2_DEFAULT_FLAGS
        )
        let code = argon2_ctx(&context, Argon2_id)
        #expect(code == ARGON2_OK.rawValue)
        let tag = hex(Data(bytes: out, count: outLen))
        #expect(tag == "0d640df58d78766c08c037a34a8b53c9d01ef0452d75b65eb52520e96b01e659")
    }

    // MARK: - Upstream test.c raw-API vectors (through PassphraseKDF)

    /// The pinned upstream's argon2id `hashtest` cases, run through OUR
    /// wrapper (same `argon2id_hash_raw` call path production uses).
    /// ASCII inputs, so NFKD normalization is a no-op by construction.
    @Test(arguments: [
        (2, 65536, 1, "password", "somesalt",
         "09316115d5cf24ed5a15a31a3ba326e5cf32edc24702987c02b6566f61913cf7"),
        (2, 262144, 1, "password", "somesalt",
         "78fe1ec91fb3aa5657d72e710854e4c3d9b9198c742f9616c2f085bed95b2e8c"),
        (2, 256, 1, "password", "somesalt",
         "9dfeb910e80bad0311fee20f9c0e2b12c17987b4cac90c2ef54d5b3021c68bfe"),
        (2, 256, 2, "password", "somesalt",
         "6d093c501fd5999645e0ea3bf620d7b8be7fd2db59c20d9fff9539da2bf57037"),
        (1, 65536, 1, "password", "somesalt",
         "f6a5adc1ba723dddef9b5ac1d464e180fcd9dffc9d1cbf76cca2fed795d9ca98"),
        (4, 65536, 1, "password", "somesalt",
         "9025d48e68ef7395cca9079da4c4ec3affb3c8911fe4f86d1a2520856f63172c"),
        (2, 65536, 1, "differentpassword", "somesalt",
         "0b84d652cf6b0c4beaef0dfe278ba6a80df6696281d7e0d2891b817d8c458fde"),
        (2, 65536, 1, "password", "diffsalt",
         "bdf32b05ccc42eb15d58fd19b1f856b113da1e9a5874fdcc544308565aa8141c"),
    ])
    func upstreamRawAPIVectors(
        _ vector: (Int, Int, Int, String, String, String)
    ) throws {
        let (t, memoryKiB, lanes, password, salt, expected) = vector
        let descriptor = PassphraseKDF.Descriptor(
            algorithm: "argon2id", argon2Version: 0x13,
            memoryKiB: memoryKiB, iterations: t, parallelism: lanes,
            salt: Data(salt.utf8), outputBytes: 32)
        let key = try PassphraseKDF.deriveKey(passphrase: password, descriptor: descriptor)
        #expect(keyHex(key) == expected)
    }

    // MARK: - The v1 default descriptor

    @Test func v1DescriptorParameters() {
        let descriptor = PassphraseKDF.Descriptor.v1(salt: Data(repeating: 1, count: 16))
        #expect(descriptor.algorithm == "argon2id")
        #expect(descriptor.argon2Version == 0x13)
        #expect(descriptor.memoryKiB == 65536)  // the ~64 MiB class, R-7
        #expect(descriptor.iterations == 3)
        #expect(descriptor.parallelism == 1)
        #expect(descriptor.outputBytes == 32)
        // OWASP floor (19 MiB / t=2) exceeded.
        #expect(descriptor.memoryKiB > 19 * 1024)
        #expect(descriptor.iterations >= 2)
    }

    /// Drift pin for the v1 default semantics (m/t/p + NFKD + output
    /// length): generated by this implementation once and pinned — a
    /// silent change here would orphan every existing vault's passphrase
    /// wrap. (Correctness itself is carried by the RFC/upstream vectors
    /// above; this pins OUR parameter/normalization envelope.)
    @Test func v1DefaultDerivationPin() throws {
        let salt = Data(repeating: 0x0A, count: 16)
        let key = try PassphraseKDF.deriveKey(
            passphrase: "correct horse battery staple",
            descriptor: .v1(salt: salt))
        #expect(keyHex(key)
            == "997ebeb60af49f854f88abefe9f277d7d4919eb8b23d6ba4928e8a004aa1647a")
    }

    /// The same characters in NFC and NFD compose forms derive the SAME
    /// key (NFKD normalization before hashing — cross-device text input).
    @Test func passphraseNormalizationIsCompositionInvariant() throws {
        let descriptor = PassphraseKDF.Descriptor(
            algorithm: "argon2id", argon2Version: 0x13,
            memoryKiB: 256, iterations: 1, parallelism: 1,
            salt: Data("somesalt".utf8), outputBytes: 32)
        let nfc = "caf\u{E9} r\u{E9}sum\u{E9}"          // precomposed é
        let nfd = "cafe\u{301} re\u{301}sume\u{301}"    // e + combining acute
        let keyNFC = try PassphraseKDF.deriveKey(passphrase: nfc, descriptor: descriptor)
        let keyNFD = try PassphraseKDF.deriveKey(passphrase: nfd, descriptor: descriptor)
        #expect(keyHex(keyNFC) == keyHex(keyNFD))
    }

    @Test func differentSaltsDifferentKeys() throws {
        let a = try PassphraseKDF.deriveKey(
            passphrase: "password",
            descriptor: PassphraseKDF.Descriptor(
                algorithm: "argon2id", argon2Version: 0x13,
                memoryKiB: 256, iterations: 1, parallelism: 1,
                salt: Data("somesalt".utf8), outputBytes: 32))
        let b = try PassphraseKDF.deriveKey(
            passphrase: "password",
            descriptor: PassphraseKDF.Descriptor(
                algorithm: "argon2id", argon2Version: 0x13,
                memoryKiB: 256, iterations: 1, parallelism: 1,
                salt: Data("diffsalt".utf8), outputBytes: 32))
        #expect(keyHex(a) != keyHex(b))
    }

    @Test func randomSaltIsSixteenFreshBytes() {
        let a = PassphraseKDF.randomSalt()
        let b = PassphraseKDF.randomSalt()
        #expect(a.count == 16)
        #expect(b.count == 16)
        #expect(a != b)
    }

    // MARK: - Typed refusals

    @Test func unsupportedAlgorithmRefuses() {
        var descriptor = PassphraseKDF.Descriptor.v1(salt: Data(repeating: 1, count: 16))
        descriptor.algorithm = "scrypt"
        #expect(throws: PassphraseKDFError.unsupportedAlgorithm("scrypt")) {
            _ = try PassphraseKDF.deriveKey(passphrase: "x", descriptor: descriptor)
        }
    }

    @Test func unsupportedVersionRefuses() {
        var descriptor = PassphraseKDF.Descriptor.v1(salt: Data(repeating: 1, count: 16))
        descriptor.argon2Version = 0x10
        #expect(throws: PassphraseKDFError.self) {
            _ = try PassphraseKDF.deriveKey(passphrase: "x", descriptor: descriptor)
        }
    }

    /// pre-13x 3b (the postures design §12; sign-off condition ii): THE
    /// DESCRIPTOR FLOOR ON READ — 19 MiB, two passes, a 16-byte salt; the
    /// v1 default clears it; each dimension below it refuses typed.
    @Test func theProductionFloorIsNineteenMiBTwoPassesAndASixteenByteSalt() throws {
        let floor = PassphraseKDF.Floor.production
        #expect(floor.memoryKiB == 19 * 1024 && floor.iterations == 2 && floor.saltBytes == 16)
        try PassphraseKDF.Descriptor.v1(salt: PassphraseKDF.randomSalt()).validateFloor(floor)
        var memory = PassphraseKDF.Descriptor.v1(salt: PassphraseKDF.randomSalt())
        memory.memoryKiB = 19 * 1024 - 1
        #expect(throws: PassphraseKDFError.self) { try memory.validateFloor(floor) }
        var passes = PassphraseKDF.Descriptor.v1(salt: PassphraseKDF.randomSalt())
        passes.iterations = 1
        #expect(throws: PassphraseKDFError.self) { try passes.validateFloor(floor) }
        let salt = PassphraseKDF.Descriptor.v1(salt: Data(repeating: 7, count: 15))
        #expect(throws: PassphraseKDFError.self) { try salt.validateFloor(floor) }
        // The test host's relaxed floor is a DEBUG-only reading of the
        // process; the production floor is the constant every Release build
        // compiles in (a compile-time fact, recorded here).
        #expect(PassphraseKDF.Floor.relaxedForTests.memoryKiB < floor.memoryKiB)
    }

    @Test func outOfRangeParametersRefuse() {
        // Empty salt, zero iterations, zero memory, oversized output —
        // each refuses with a typed error, never reaching the C call.
        var descriptor = PassphraseKDF.Descriptor.v1(salt: Data())
        #expect(throws: PassphraseKDFError.self) {
            _ = try PassphraseKDF.deriveKey(passphrase: "x", descriptor: descriptor)
        }
        descriptor = .v1(salt: Data(repeating: 1, count: 16))
        descriptor.iterations = 0
        #expect(throws: PassphraseKDFError.self) {
            _ = try PassphraseKDF.deriveKey(passphrase: "x", descriptor: descriptor)
        }
        descriptor = .v1(salt: Data(repeating: 1, count: 16))
        descriptor.memoryKiB = 0
        #expect(throws: PassphraseKDFError.self) {
            _ = try PassphraseKDF.deriveKey(passphrase: "x", descriptor: descriptor)
        }
        descriptor = .v1(salt: Data(repeating: 1, count: 16))
        descriptor.outputBytes = 1024
        #expect(throws: PassphraseKDFError.self) {
            _ = try PassphraseKDF.deriveKey(passphrase: "x", descriptor: descriptor)
        }
    }

    // MARK: - Descriptor codability (the vault stores it)

    @Test func descriptorRoundTripsThroughJSON() throws {
        let descriptor = PassphraseKDF.Descriptor.v1(salt: PassphraseKDF.randomSalt())
        let data = try JSONEncoder().encode(descriptor)
        let decoded = try JSONDecoder().decode(PassphraseKDF.Descriptor.self, from: data)
        #expect(decoded == descriptor)
    }

    // MARK: - Latency harness (R-7: on-device latency measured — the Mac
    // half; the phone half rides batch 3's device work)

    @Test func kdfLatencyHarnessMac() throws {
        let descriptor = PassphraseKDF.Descriptor.v1(salt: PassphraseKDF.randomSalt())
        var samples: [Double] = []
        for _ in 0..<3 {
            let start = ContinuousClock.now
            _ = try PassphraseKDF.deriveKey(
                passphrase: "a plausible encryption passphrase", descriptor: descriptor)
            let elapsed = ContinuousClock.now - start
            samples.append(
                Double(elapsed.components.seconds) + Double(elapsed.components.attoseconds) / 1e18)
        }
        let sorted = samples.sorted()
        let median = sorted[1]
        print(
            "KDF-LATENCY (Mac, v1 descriptor m=64MiB t=3 p=1): "
                + samples.map { String(format: "%.3fs", $0) }.joined(separator: " ")
                + String(format: " — median %.3fs", median))
        // Sanity envelope only (R-7 stated ~0.5–1 s as the class; the Mac
        // is the fast end). Not a perf gate — the printed number is the
        // deliverable.
        #expect(median > 0.01)
        #expect(median < 5.0)
    }
}
